<template>
  <section class="assistant-dashboard">
    <div class="page-heading"><div><p class="eyebrow">{{ identity.agencyName || 'Assigned agency' }}</p><h1>{{ identity.displayName || 'Assistant dashboard' }}</h1><p class="subtitle">{{ identity.subrole ? roleLabel(identity.subrole) : 'No duties assigned.' }}</p></div><button type="button" @click="load" :disabled="loading || busy">Refresh</button></div>
    <p v-if="error" role="alert" class="notice notice--error">{{ error }}</p>
    <p v-if="message" role="status" class="notice">{{ message }}</p>
    <p v-if="loading" role="status">Loading your workspace…</p>
    <template v-else>
      <div v-if="!identity.capabilities?.length" class="empty-state"><h2>Your dashboard is ready</h2><p>No work or data access has been assigned to this account.</p></div>
      <template v-else>
        <div class="scope-line"><span class="badge">{{ identity.status || 'pending' }}</span><span>Policy {{ identity.policyRevision || 'not supplied' }}</span><span>One agency · {{ identity.agencyName }}</span></div>
        <section v-if="identity.subrole==='team_lead'" class="panel team-readiness">
          <div class="section-heading"><div><h2>Team readiness</h2><p>Queue approved work for this agency and check returned result and verification status.</p><p class="muted">Current task policy: {{ currentPolicyVersion || 'Not supplied' }}</p></div><button v-if="identity.capabilities?.includes('team_lead.dispatch')" type="button" @click="dispatch" :disabled="busy || activeRun!==null">Queue due tasks</button></div>
          <div v-if="team.length" class="team-table-scroll"><table><thead><tr><th>Assistant</th><th>Status</th><th>Result and verification</th></tr></thead><tbody><tr v-for="member in team" :key="member.id || member.subrole"><td>{{ member.displayName || roleLabel(member.subrole) }}</td><td>{{ member.status }}<span v-if="member.preparingCount"> · {{ member.preparingCount }} preparing</span><span v-if="member.blockedCount"> · {{ member.blockedCount }} blocked</span></td><td>{{ member.lastOutcome || member.lastResult || 'No result yet' }}<div class="evidence-status" :class="{'evidence-status--missing':member.lastEvidenceComplete===false}">{{ evidenceLabel(member.lastEvidenceComplete) }}</div><div v-if="member.lastStartedAt" class="muted">Started {{ date(member.lastStartedAt) }}</div><div v-if="member.lastDurationSeconds!=null" class="muted">Duration: {{ duration(member.lastDurationSeconds) }}</div><div class="muted">{{ verificationSummary(member) }}</div></td></tr></tbody></table></div><p v-else class="muted">No team status is available.</p>
          <div v-if="assignments.length && identity.capabilities?.includes('team_lead.dispatch')" class="lead-assignments"><h3>Team task priorities</h3><p class="muted">Priorities reorder this agency's existing work. They do not change duties or permissions.</p><div v-for="assignment in assignments" :key="assignment.ref" class="task-row"><div><h3>{{ assignment.title }}</h3><p>{{ roleLabel(assignment.subrole) }} · {{ assignment.status }}<span v-if="assignment.dueAt"> · Due {{ date(assignment.dueAt) }}</span></p></div><label>Priority<select :value="Number(assignment.priority)||0" @change="prioritize(assignment,$event)" :disabled="busy || assignment.status!=='queued'"><option :value="0">Normal</option><option :value="1">High</option><option :value="2">Urgent</option></select></label></div></div>
          <div v-if="identity.capabilities?.includes('team_lead.review')" class="lead-retests"><h3>Request a scoped retest</h3><p class="muted">Send Michael a fixed-category retest request for an existing duty. Requests do not grant access or activate a capability.</p><template v-for="member in team" :key="`retest-${member.subrole}`"><form v-if="member.availableCapabilities?.length && retestForms[member.subrole]" class="retest-form" @submit.prevent="requestRetest(member)"><h4>{{ member.displayName || roleLabel(member.subrole) }}</h4><div class="form-grid"><label>Duty<select v-model="retestForms[member.subrole].capability" :disabled="busy"><option v-for="capability in member.availableCapabilities" :key="capability" :value="capability">{{ capability }}</option></select></label><label>Reason<select v-model="retestForms[member.subrole].reasonCode" :disabled="busy"><option value="workflow_failure">Workflow failed</option><option value="privacy_boundary">Privacy boundary needs review</option><option value="stale_sources">Sources changed or became stale</option><option value="missing_evidence">Verification evidence is missing</option></select></label></div><button type="submit" class="secondary" :disabled="busy || !retestForms[member.subrole].capability">Request retest</button></form></template></div>
        </section>
        <section v-if="identity.capabilities?.includes('payroll.report_to_team')" class="panel"><h2>Morning payroll report</h2><p>Review today’s saved results, then send one report to this agency’s configured payroll team.</p><button type="button" @click="previewDailyReport" :disabled="busy || !!activeRun">Review daily report</button><template v-if="dailyReport"><p class="muted">Delivery status: {{ dailyReport.status }}. Sender acceptance does not confirm mailbox receipt.</p><pre class="report-preview">{{ dailyReport.preview.text }}</pre><button type="button" @click="sendDailyReport" :disabled="busy || !!activeRun || dailyReport.status!=='draft'">Send reviewed report to payroll</button></template></section><section class="panel"><h2>Assigned work</h2><p v-if="!tasks.length" class="muted">No tasks are waiting. Refresh when your next run is due.</p><div v-for="task in tasks" :key="task.ref" class="task-row"><div><h3>{{ task.title }}</h3><p>{{ roleLabel(task.taskKind) }} · {{ task.status }}<span v-if="task.dueAt"> · Due {{ date(task.dueAt) }}</span></p></div><button type="button" @click="start(task)" :disabled="busy || !!activeRun || !['queued','pending','retry','ready','leased'].includes(task.status)">{{ task.status==='leased' ? 'Resume task' : 'Open task' }}</button></div></section>
        <section v-if="activeRun" class="panel run-panel"><div class="section-heading"><div><p class="eyebrow">Current task</p><h2>{{ activeRun.title }}</h2><p class="muted">{{ leaseMessage }}</p></div><span class="badge">In progress</span></div><AssistantPacket :value="visiblePacket" /><AssistantSupervisionHistory v-if="activeRun.packet?.supervision" :value="activeRun.packet.supervision" /><section v-if="activeRun.packet?.providerReviewAvailable" class="panel payroll-review"><h3>Payroll submission review</h3><button type="button" class="secondary" @click="loadProviderDetails" :disabled="busy || leaseLost">Who submitted this? Provider details</button><AssistantPacket v-if="providerDetails" :value="visibleProvider" /><p>Review the provider role and credential, then apply your external duty instructions. A supervisor's payable time is separate from an LPCC supervisee's attendance. Keep all time and pay terms unchanged.</p><p v-if="activeRun.packet.approval && !activeRun.packet.approval.eligible">This submission requires a person to review the listed checks. Record the exception below.</p><button v-if="activeRun.packet.approval && identity.capabilities?.includes(activeRun.packet.approval.capability)" type="button" @click="approvePayroll" :disabled="busy || leaseLost || !providerDetails || !activeRun.packet.approval.eligible || !result.steps.trim() || !result.buildId.trim()">Approve reviewed submission</button><p class="muted">Enter the observed build and review steps below before approving. This saves the approval and its evidence; it does not run or post payroll.</p></section><section v-if="identity.capabilities?.includes('marketing.publish') && activeRun.packet?.approvedVariants?.length" class="marketing-review"><h3>Approved website variants</h3><p class="muted">Choose only an owner-approved variant for this task. Compare the preview and check the rendered result before publishing.</p><label>Approved variant<select v-model="marketing.variantKey"><option disabled value="">Choose variant</option><option v-for="variant in activeRun.packet.approvedVariants" :key="variant.key" :value="variant.key">{{ variant.label || variant.key }}</option></select></label><button type="button" class="secondary" @click="previewMarketing" :disabled="busy || !marketing.variantKey || leaseLost">Preview variant</button><div v-if="marketing.preview"><div class="form-grid"><div class="marketing-copy"><h4>Current copy</h4><AssistantPacket :value="marketing.preview.before" /></div><div class="marketing-copy"><h4>Approved variant</h4><AssistantPacket :value="marketing.preview.after" /></div></div><label class="check"><input type="checkbox" v-model="marketing.desktopChecked" />I checked the desktop rendering.</label><label class="check"><input type="checkbox" v-model="marketing.mobileChecked" />I checked the narrow phone rendering.</label><label class="check"><input type="checkbox" v-model="marketing.linksPreserved" />The existing links and their destinations are preserved.</label><button type="button" @click="publishMarketing" :disabled="busy || leaseLost || !!marketing.revisionRef || !marketing.desktopChecked || !marketing.mobileChecked || !marketing.linksPreserved">Publish approved variant</button><p v-if="marketing.revisionRef" role="status" class="notice">Published revision {{ marketing.revisionRef }}. Record the rendered result in your findings.</p></div></section><form @submit.prevent="complete" class="result-form"><h3>Record the result</h3><label>Outcome<select v-model="result.outcome"><option value="PASS">PASS — expected result verified</option><option value="FAIL">FAIL — actual result differs</option><option value="BLOCKED">BLOCKED — required access or evidence missing</option><option value="NOT_RUN">NOT RUN — task not attempted</option></select></label><fieldset><legend>Findings</legend><div v-for="(finding,index) in result.findings" :key="index" class="finding"><div class="form-grid"><label>Category<input v-model="finding.category" required maxlength="80" /></label><label>Severity<select v-model="finding.severity"><option value="review">Review</option><option value="warning">Warning</option><option value="blocker">Blocker</option><option value="improvement">Improvement</option></select></label></div><label>Observed result<textarea v-model="finding.message" required rows="3" maxlength="2000" /></label><label>Source references, one per line<textarea v-model="finding.sourceText" rows="2" placeholder="Use the source references supplied in this task." /></label><label>Recommended next action<textarea v-model="finding.recommendation" rows="2" maxlength="2000" /></label><label>Uncertainty or missing evidence<input v-model="finding.uncertainty" maxlength="1000" /></label><button v-if="result.findings.length>1" type="button" class="secondary" @click="result.findings.splice(index,1)">Remove finding</button></div><button type="button" class="secondary" @click="addFinding">Add finding</button></fieldset><label>Steps and verification, one per line<textarea v-model="result.steps" required rows="4" placeholder="Describe what you checked and the expected versus actual result. Do not include passwords, tokens or private links." /></label><label>Release build<input v-model="result.buildId" required maxlength="100" placeholder="Build shown in the release evidence" /></label><p class="muted">The result includes this browser, viewport, observation time and the task's saved source revision.</p><button type="submit" :disabled="busy || leaseLost">Submit result</button></form></section>
      </template>
    </template>
  </section>
</template>
<script setup>
import { computed, onMounted, onBeforeUnmount, ref } from 'vue';
import api from '../../services/api';
import AssistantPacket from '../../components/assistants/AssistantPacket.vue';
import AssistantSupervisionHistory from '../../components/assistants/AssistantSupervisionHistory.vue';
const identity=ref({}),tasks=ref([]),team=ref([]),assignments=ref([]),retestForms=ref({}),currentPolicyVersion=ref(''),loading=ref(true),busy=ref(false),error=ref(''),message=ref(''),activeRun=ref(null),leaseLost=ref(false);
const providerDetails=ref(null),dailyReport=ref(null);
const visiblePacket=computed(()=>{const {supervision,...rest}=activeRun.value?.packet||{};return rest;});
const visibleProvider=computed(()=>{const {superviseeSupervision,...rest}=providerDetails.value||{};return rest;});
const result=ref({outcome:'PASS',findings:[],steps:'',buildId:''});const marketing=ref({variantKey:'',preview:null,desktopChecked:false,mobileChecked:false,linksPreserved:false,revisionRef:null});let heartbeat=null;
const roleLabel = value => String(value || '').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const date = value => {const d=new Date(value);return Number.isNaN(d.getTime())?'Not supplied':d.toLocaleString(undefined,{timeZone:'America/Denver'});};
const errorText = e => e?.response?.data?.error?.message || e?.response?.data?.message || 'The request could not be completed. Refresh before retrying.';
const leaseMessage = computed(()=>leaseLost.value?'Task access needs to be refreshed. Save your findings and ask the team lead to review this run.':`Task lease expires ${date(activeRun.value?.leaseExpiresAt)}.`);
function addFinding(){result.value.findings.push({category:'review',severity:'review',message:'',sourceText:'',recommendation:'',uncertainty:''});}
async function load(){loading.value=true;error.value='';try{const {data}=await api.get('/assistant-work');identity.value=data.identity||{};tasks.value=data.tasks||[];team.value=data.team||[];assignments.value=data.assignments||[];currentPolicyVersion.value=data.currentPolicyVersion||'';for(const member of team.value){const allowed=member.availableCapabilities||[];const previous=retestForms.value[member.subrole];retestForms.value[member.subrole]={capability:allowed.includes(previous?.capability)?previous.capability:allowed[0]||'',reasonCode:previous?.reasonCode||'workflow_failure'};}}catch(e){error.value=errorText(e);}finally{loading.value=false;}}
const evidenceLabel=value=>value===true?'Evidence complete':value===false?'Evidence missing':'Evidence not recorded';
const duration=value=>{const seconds=Number(value);if(!Number.isFinite(seconds)||seconds<0)return 'Not recorded';const total=Math.round(seconds),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60),remainder=total%60;return [hours?`${hours}h`:null,minutes?`${minutes}m`:null,`${remainder}s`].filter(Boolean).join(' ');};
function verificationSummary(member){const receipts=member.verification||member.verifications||[];return Array.isArray(receipts)&&receipts.length?receipts.map(v=>`${v.capability}: ${v.outcome||'not recorded'}${v.policyVersion?' · '+v.policyVersion:''}`).join(' · '):'No verification recorded';}
async function prioritize(assignment,event){busy.value=true;error.value='';message.value='';try{await api.post(`/assistant-work/tasks/${encodeURIComponent(assignment.ref)}/priority`,{priority:Number(event.target.value)});message.value='Task priority updated.';await load();}catch(e){event.target.value=Number(assignment.priority)||0;error.value=errorText(e);}finally{busy.value=false;}}
async function requestRetest(member){const form=retestForms.value[member.subrole];if(!form||!(member.availableCapabilities||[]).includes(form.capability))return;busy.value=true;error.value='';message.value='';try{const {data}=await api.post('/assistant-work/retest-request',{subrole:member.subrole,capability:form.capability,reasonCode:form.reasonCode});message.value=data.reused?'A retest request for this duty is already recorded today.':'Retest requested for Michael to review.';}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function dispatch(){busy.value=true;error.value='';message.value='';try{const {data}=await api.post('/assistant-work/dispatch');message.value=`${data.queued||0} preparation request(s) queued; ${data.skipped||0} skipped.`;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function start(task){providerDetails.value=null;busy.value=true;error.value='';message.value='';try{const {data}=await api.post(`/assistant-work/tasks/${encodeURIComponent(task.ref)}/start`);activeRun.value={...data,title:task.title,taskRef:task.ref};marketing.value={variantKey:'',preview:null,desktopChecked:false,mobileChecked:false,linksPreserved:false,revisionRef:null};leaseLost.value=false;result.value={outcome:'PASS',findings:[],steps:'',buildId:''};addFinding();try{const version=await fetch('/version.json',{cache:'no-store'}).then(r=>r.ok?r.json():{});result.value.buildId=version.buildId||'';}catch{};clearInterval(heartbeat);heartbeat=setInterval(renewLease,45000);}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function previewMarketing(){busy.value=true;error.value='';try{const {data}=await api.post('/assistant-work/marketing/preview',{taskRef:activeRun.value.taskRef,variantKey:marketing.value.variantKey});marketing.value={...marketing.value,preview:data,desktopChecked:false,mobileChecked:false,linksPreserved:false,revisionRef:null};}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function publishMarketing(){busy.value=true;error.value='';try{const preview=marketing.value.preview;const {data}=await api.post('/assistant-work/marketing/publish',{previewRef:preview.previewRef,sourceRevision:preview.sourceRevision,evidence:{desktopChecked:marketing.value.desktopChecked,mobileChecked:marketing.value.mobileChecked,linksPreserved:marketing.value.linksPreserved}});marketing.value.revisionRef=data.revisionRef;if(data.sourceRevision)activeRun.value.sourceRevision=data.sourceRevision;}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function renewLease(){if(!activeRun.value||leaseLost.value)return;try{const {data}=await api.post(`/assistant-work/runs/${encodeURIComponent(activeRun.value.runRef)}/heartbeat`);if(data.leaseExpiresAt)activeRun.value.leaseExpiresAt=data.leaseExpiresAt;}catch(e){leaseLost.value=true;error.value=errorText(e);clearInterval(heartbeat);}}
async function previewDailyReport(){busy.value=true;error.value='';try{const{data}=await api.get('/assistant-work/payroll/report');dailyReport.value=data;}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function sendDailyReport(){busy.value=true;error.value='';try{const{data}=await api.post('/assistant-work/payroll/report/send',{reportRef:dailyReport.value.reportRef,sourceRevision:dailyReport.value.sourceRevision});dailyReport.value.status=data.queued?'pending':dailyReport.value.status;message.value=data.queued?'Reviewed report queued for the payroll team. Delivery and receipt still need verification.':'This daily report has already been queued.';}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function loadProviderDetails(){busy.value=true;error.value='';try{const ref=activeRun.value.packet.items?.[0]?.staffRef;const{data}=await api.get(`/assistant-work/runs/${encodeURIComponent(activeRun.value.runRef)}/providers/${encodeURIComponent(ref)}`);providerDetails.value=data;}catch(e){providerDetails.value=null;error.value=errorText(e);}finally{busy.value=false;}}
async function approvePayroll(){busy.value=true;error.value='';try{await api.post(`/assistant-work/runs/${encodeURIComponent(activeRun.value.runRef)}/payroll/approve`,{sourceRevision:activeRun.value.sourceRevision,evidence:{browser:navigator.userAgent.slice(0,100),viewport:`${window.innerWidth}x${window.innerHeight}`,buildId:result.value.buildId,observedAt:new Date().toISOString(),steps:result.value.steps.split('\n').map(s=>s.trim()).filter(Boolean)}});clearInterval(heartbeat);activeRun.value=null;providerDetails.value=null;message.value='Reviewed submission approved. Payroll preparation remains with the payroll person.';await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function complete(){busy.value=true;error.value='';try{const body={sourceRevision:activeRun.value.sourceRevision,outcome:result.value.outcome,findings:result.value.findings.map(({sourceText,...finding})=>({...finding,sourceRefs:sourceText.split('\n').map(s=>s.trim()).filter(Boolean)})),evidence:{browser:navigator.userAgent.slice(0,100),viewport:`${window.innerWidth}x${window.innerHeight}`,buildId:result.value.buildId,observedAt:new Date().toISOString(),steps:result.value.steps.split('\n').map(s=>s.trim()).filter(Boolean)}};await api.post(`/assistant-work/runs/${encodeURIComponent(activeRun.value.runRef)}/complete`,body);clearInterval(heartbeat);activeRun.value=null;message.value='Result saved for team lead review.';await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
onMounted(load);onBeforeUnmount(()=>clearInterval(heartbeat));
</script>
<style scoped>
.report-preview{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.6}.page-heading,.section-heading,.task-row{display:flex;align-items:flex-start;justify-content:space-between;gap:20px}.page-heading{margin-bottom:26px}h1{font-size:30px;margin:5px 0 10px}h2{font-size:20px;margin:0 0 12px}h3{font-size:16px;margin:0 0 7px}.eyebrow{color:#326c62;font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;margin:0}.subtitle,.muted,.task-row p{color:#5d727c;font-size:14px;line-height:1.6}.panel,.empty-state{padding:24px;background:#fff;border:1px solid #d9e3e7;border-radius:12px;margin-bottom:20px}.empty-state{min-height:220px;display:flex;justify-content:center;flex-direction:column}.scope-line{display:flex;gap:20px;align-items:center;flex-wrap:wrap;margin-bottom:20px;font-size:13px;color:#596f78}.badge{border-radius:20px;background:#e8f2ed;padding:5px 11px;font-size:12px;color:#2d6755}.notice{border:1px solid #bfd5cd;padding:14px;border-radius:8px;background:#eff7f2}.notice--error{border-color:#e6b4b4;background:#fff0f0;color:#8e2424}button{padding:10px 15px;white-space:nowrap;border:0;border-radius:7px;background:#245e55;color:#fff;cursor:pointer;font-weight:600}button:disabled{opacity:.45;cursor:not-allowed}.secondary{background:#eaf0f2;color:#264b52}.task-row{padding:18px 0;border-top:1px solid #e4ebee}.task-row p{margin:0}.marketing-review{margin-top:24px;padding:20px;border:1px solid #d5e4dc;border-radius:8px;display:grid;gap:14px}.marketing-copy{padding:16px;background:#f4f8f7;border-radius:7px}.marketing-copy h4{margin:0 0 12px}.check{display:flex;align-items:center;gap:8px}.check input{width:auto}.evidence-status{font-size:12px;font-weight:700;color:#326657;margin-top:7px}.evidence-status--missing{color:#925029}.team-table-scroll{max-width:100%;overflow-x:auto}.lead-assignments,.lead-retests{margin-top:26px;padding-top:22px;border-top:1px solid #dce6e9}.retest-form{padding:18px;margin:16px 0;background:#f5f8f9;border:1px solid #dbe5e8;border-radius:8px;display:grid;gap:14px}.retest-form h4{margin:0}.result-form{margin-top:28px;padding-top:24px;border-top:1px solid #dae4e8;display:grid;gap:17px}label{display:grid;gap:7px;font-size:13px;font-weight:600}input,textarea,select{font:inherit;font-weight:400;padding:10px;border:1px solid #bfcfd5;border-radius:6px;min-width:0;width:100%;box-sizing:border-box}textarea{resize:vertical;line-height:1.5}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}fieldset{border:1px solid #d5e0e5;padding:18px;border-radius:8px}.finding{display:grid;gap:14px;margin-bottom:20px;padding-bottom:20px;border-bottom:1px solid #e5ebee}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:12px;border-bottom:1px solid #e3eaed}@media(max-width:640px){.page-heading,.section-heading,.task-row{flex-direction:column}.panel{padding:18px}.form-grid{grid-template-columns:1fr}h1{font-size:25px}.scope-line{gap:10px}}
</style>
